async () => {
const s=await connecta.search({query:"data source schema",connector:"notion_bot"});
const t=await connecta.search({query:"query data source",connector:"notion_bot"});
const a=await connecta.call("notion_bot.integration_get_data_source_schema",{data_source_id:"ds-roadmap"});
