async () => {
const s=await connecta.call("notion_bot.integration_get_data_source_schema",{data_source_id:"ds-roadmap"});
const q=await connecta.call("notion_bot.integration_query_data_source",{data_source_id:"ds-roadmap",page_size:100});
return {schema:s.data, rows:(q.data?.results||[]).map(x=>({title:x.title,properties:x.properties})),more:q.data?.has_more};
}

async () => {
let cur, titles=[], pages=0;
do {
 const r=await connecta.call("notion_bot.integration_query_data_source",{data_source_id:"ds-roadmap",page_size:100,...(cur?{start_cursor:cur}:{})});
 const d=r.data; pages++;
 for(const x of d.results||[]) if(x.properties?.Status==="Blocked") titles.push(x.title);
 cur=d.has_more?d.next_cursor:null;
} while(cur && pages<30);
return {count:titles.length,titles,pages};
}

